const raw = String($('Webhook').first().json.body.image_b64 || "").trim();
// Ollama expects raw base64, not a data URL such as "data:image/png;base64,...."
const b64 = raw.replace(/^data:[^;,]+;base64,/i, "");
return [{ json: { b64 } }];

let o = {};
try { o = JSON.parse($json.message.content); } catch (e) {}
const t = String(o.type || "").toLowerCase();
const confidence = Number(o.confidence) || 0;
let type = t.startsWith("not") ? "not_food"
  : (t.includes("document") || t.includes("recipe")) ? "recipe_document"
  : t.includes("dish") ? "dish_photo" : "ingredients_photo";
// only reject an image when the model is sure it is not food
if (type === "not_food" && confidence < 0.6) type = "ingredients_photo";
return [{ json: { type, confidence, visible: String(o.visible || "").slice(0, 120) } }];

const body = $('Webhook').first().json.body || {};
const f = body.filters || {};
const max_minutes = f.max_minutes || null;
const max_calories = f.max_kcal || null;
const vegetarian = f.vegetarian === true;
const cuisine = f.cuisine || null;
const min_protein = f.min_protein_g || null;

const userText = String(body.query || "").trim();
const hasText = userText.length > 0;
const clean = s => String(s || "").toLowerCase().replace(/[^\p{L}\s'-]/gu, " ").replace(/\s+/g, " ").trim();

const llm_failed = !!$json.error;
let o = {};
try { o = JSON.parse($json.message.content); } catch (e) {}

// --- ingredients seen in the photo ---
const seen = new Set(), ing = [], dropped = [];
for (const i of (Array.isArray(o.ingredients) ? o.ingredients : []).slice(0, 25)) {
  const name = clean(i && typeof i === "object" ? i.name : i);
  if (!name || seen.has(name)) continue;
  seen.add(name);
  const c = i && typeof i === "object" && i.confidence !== undefined ? Number(i.confidence) : 1;
  (c >= 0.6 ? ing : dropped).push(name);
}
const uncertain = [...new Set(dropped.concat(Array.isArray(o.uncertain) ? o.uncertain.map(clean) : []).filter(Boolean))];

// Ingredients found in the photo => ingredients mode (typed text is only an extra hint).
// Nothing found => fall back to a dish search on the typed text.
const title_query = hasText ? clean(userText) : "";
const mode = ing.length ? "ingredients" : "dish";
const source = hasText ? "text+photo" : "photo";

const queryParts = [];
if (title_query) queryParts.push(title_query);
if (ing.length) queryParts.push("Ingredients: " + ing.join(", "));
const query = queryParts.join(" | ");

return [{ json: {
  mode, source, query, title_query,
  user_ingredients: ing, uncertain, llm_failed,
  max_minutes, max_calories, vegetarian, cuisine, min_protein
} }];

const body = $('Webhook').first().json.body || {};
const f = body.filters || {};
const max_minutes = f.max_minutes || null;
const max_calories = f.max_kcal || null;
const vegetarian = f.vegetarian === true;
const cuisine = f.cuisine || null;
const min_protein = f.min_protein_g || null;

