const hasText = userText.length > 0;
const clean = s => String(s || "").toLowerCase().replace(/[^\p{L}\s'-]/gu, " ").replace(/\s+/g, " ").trim();

const llm_failed = !!$json.error;
let o = {};
try { o = JSON.parse($json.message.content); } catch (e) {}

const photoDish = clean(o.dish || o.title || "");
const alt = Array.isArray(o.alternatives) ? clean(o.alternatives[0] || "") : "";
const mains = [...new Set((Array.isArray(o.main_ingredients) ? o.main_ingredients : []).map(clean).filter(Boolean))].slice(0, 6);
const conf = Number(o.confidence) || 0;

// The user's own words win over the photo.
const dish = hasText ? clean(userText) : (photoDish || alt);

// Photo dish unknown or very uncertain: search by its main ingredients instead of guessing a name.
if (!hasText && (!dish || conf < 0.4) && mains.length >= 2) {
  return [{ json: {
    mode: "ingredients", source: "photo",
    query: "Ingredients: " + mains.join(", "), title_query: "",
    user_ingredients: mains, uncertain: [], llm_failed,
    max_minutes, max_calories, vegetarian, cuisine, min_protein
  } }];
}

return [{ json: {
  mode: "dish", source: hasText ? "text+photo" : "photo",
  query: dish, title_query: dish,
  user_ingredients: [], uncertain: [], llm_failed,
  max_minutes, max_calories, vegetarian, cuisine, min_protein
} }];

