const body = $('Webhook').first().json.body || {};
const raw = String(body.query || "").trim();
const f = body.filters || {};
let o = {};
try { o = JSON.parse($json.message.content); } catch (e) {}

if (raw.length < 2 || raw.startsWith("/") || o.intent === "help") {
  return [{ json: { mode: "help", source: "text", query: "", user_ingredients: [], uncertain: [],
    max_minutes: null, max_calories: null, vegetarian: false, cuisine: null, min_protein: null } }];
}

const items = [...new Set((Array.isArray(o.items) ? o.items : [])
  .map(x => String(x).toLowerCase().trim()).filter(Boolean))];
// UI filters take priority; LLM-extracted filters are the fallback
const maxMin = f.max_minutes || (Number(o.max_minutes) > 0 ? Number(o.max_minutes) : null);
const maxCal = f.max_kcal || (Number(o.max_calories) > 0 ? Number(o.max_calories) : null);
const veg = f.vegetarian === true || o.vegetarian === true;
const cuisine = f.cuisine || null;
const min_protein = f.min_protein_g || null;

if (o.intent === "ingredients" && items.length) {
  return [{ json: { mode: "ingredients", source: "text", query: "Ingredients: " + items.join(", "), title_query: "",
    user_ingredients: items, uncertain: [], max_minutes: maxMin, max_calories: maxCal, vegetarian: veg,
    cuisine, min_protein } }];
}

// If the intent model failed or answered badly, the raw text is still a usable dish query.
const dish = ((o.dish && String(o.dish).trim()) || raw).toLowerCase();
return [{ json: { mode: "text", source: "text", query: dish, title_query: dish, user_ingredients: [], uncertain: [],
  max_minutes: maxMin, max_calories: maxCal, vegetarian: veg, cuisine, min_protein } }];

const j = $json || {};
let error = "I could not detect any ingredients or request. Type what you have or upload a photo.";
let code = "NO_QUERY";
if (j.llm_failed) {
  error = "The AI model did not respond. Check that Ollama is running, then try again.";
  code = "MODEL_UNAVAILABLE";
} else if (j.mode === "help") {
  error = "Tell me what you have (for example: eggs, tomatoes, feta), a dish you are craving, or upload a photo of your fridge, a dish or a recipe.";
  code = "HELP";
} else if (j.unreadable) {
  error = "I could not read a recipe in this image. Try a sharper photo that shows the whole recipe.";
  code = "DOCUMENT_UNREADABLE";
} else if (j.source === "photo" || j.source === "text+photo") {
  error = "I could not recognize any ingredient or dish in this photo. Try a clearer photo, or type what you have.";
  code = "PHOTO_EMPTY";
}
return [{ json: { error, code } }];

